/* From Uiverse.io by alexruix - Tags: subscription, input */
.__UIV_SCOPE__ .input-group {
  display: flex;
  align-items: center;
}

.__UIV_SCOPE__ .input {
  min-height: 50px;
  max-width: 150px;
  padding: 0 1rem;
  color: #fff;
  font-size: 15px;
  border: 1px solid #5e4dcd;
  border-radius: 6px 0 0 6px;
  background-color: transparent;
}

.__UIV_SCOPE__ .button--submit {
  min-height: 50px;
  padding: .5em 1em;
  border: none;
  border-radius: 0 6px 6px 0;
  background-color: #5e4dcd;
  color: #fff;
  font-size: 15px;
  cursor: pointer;
  transition: background-color .3s ease-in-out;
}

.__UIV_SCOPE__ .button--submit:hover {
  background-color: #5e5dcd;
}

.__UIV_SCOPE__ .input:focus, .__UIV_SCOPE__ .input:focus-visible {
  border-color: #3898EC;
  outline: none;
}
